INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52611, 'Exodus 15:10', 'Exodus', 15, 10, 'خو تا وکړ یو پوکی او کړل لاندې بحیرې هغوی په زورورو اوبو کې هغوی ډوب شول لکه د سرپو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_10.mp3', '', 1761754199, 1761754199),
(52612, 'Exodus 15:11', 'Exodus', 15, 11, 'د خدایانو منځ کې څوک ستا په شان دی ای څښتنه؟ څوک دی ستا په شان؟ ته سپېڅلی یې او لوی یې ستا جلال دی هیبتناکه ته کوې عجیب عجیب کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_11.mp3', '', 1761754199, 1761754199),
(52613, 'Exodus 15:12', 'Exodus', 15, 12, 'تا کړ اوږد خپل ښي لاس او ژوندي تېر کړل ځمکې زمونږ دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_12.mp3', '', 1761754199, 1761754199),
(52614, 'Exodus 15:13', 'Exodus', 15, 13, 'تل ولاړ په خپل وعده یې کړې به خپل قوم ته لارښوونه کوم چې ژغورلی دی تا په خپل قوت سره به بوځې ته هغوی سپېڅلې ځمکې ته خپل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_13.mp3', '', 1761754199, 1761754199),
(52615, 'Exodus 15:14', 'Exodus', 15, 14, 'شي قومونه به خبر او په لړزان به شي د فلسطین په قوم به راشي سخته وېره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_14.mp3', '', 1761754199, 1761754199),
(52616, 'Exodus 15:15', 'Exodus', 15, 15, 'وبه وېریږي ډېر د ادوم مشران شي په لړزه به د موآب مشران د کنعان خلک به له لاسه ورکړي خپل همت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_15.mp3', '', 1761754199, 1761754199),
(52617, 'Exodus 15:16', 'Exodus', 15, 16, 'په هغوی باندې به پرېوځي سخته وېره او لړزه ستا د مټ په زور باندې به وي غلي هغوی لکه د تیږې په شان تر هغه وخته پورې ترڅو تېر شي ای څښتنه ستا قوم ترڅو تېر شي ستا قوم چې ازاد کړی دی تا د غلامۍ نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_16.mp3', '', 1761754199, 1761754199),
(52618, 'Exodus 15:17', 'Exodus', 15, 17, 'ته به راولې هغوی دننه او ځای په ځای به یې کړې ته په خپل غره باندې هغه ځای څښتنه چې غوره کړی دی تا د خپل کور دپاره سپېڅلی ځای چې ودان کړی تا په خپله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_17.mp3', '', 1761754199, 1761754199),
(52619, 'Exodus 15:18', 'Exodus', 15, 18, 'پاچاهي به کاندي تل ترتله به څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_18.mp3', '', 1761754199, 1761754199),
(52620, 'Exodus 15:19', 'Exodus', 15, 19, 'کله چې د فرعون اسونه، جنګي ګاډۍ او سپاره بحیرې ته ورداخل شول، څښتن په هغوی باندې اوبه بېرته راوستلې. خو اسراییلیان په بحیره کې په وچه ځمکه باندې تېر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_19.mp3', '', 1761754199, 1761754199),
(52621, 'Exodus 15:20', 'Exodus', 15, 20, 'بیا مریم د هارون خور چې پیغمبره وه په خپل لاس کې یوه چمبه واخیستله او ټولې ښځې د چمبو سره ورپسې شوې او نڅا یې کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_20.mp3', '', 1761754199, 1761754199),
(52622, 'Exodus 15:21', 'Exodus', 15, 21, 'مریم د هغوی دپاره دا سندره وویله: سندره ووایئ څښتن ته ځکه هغه بریالی شوی دی په سرلوړۍ سره هغه اسونه او سپاره دي غورځولي بحیرې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_21.mp3', '', 1761754199, 1761754199),
(52623, 'Exodus 15:22', 'Exodus', 15, 22, 'بیا موسی اسراییلیان د سرې بحیرې څخه د شور دښتې ته بوتلل. درې ورځې هغوی په دښته کې روان وو، خو اوبه یې ونه موندلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_22.mp3', '', 1761754199, 1761754199),
(52624, 'Exodus 15:23', 'Exodus', 15, 23, 'بیا هغوی یو ځای ته چې ماره نومېده، راغلل. خو د هغه ځای اوبه ډېرې ترخې وې او هغوی نه شو کولای چې هغه وڅښي. له دې امله په هغه باندې د ماره نوم کېښودل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_23.mp3', '', 1761754199, 1761754199),
(52625, 'Exodus 15:24', 'Exodus', 15, 24, 'نو خلک د موسی په وړاندې راپورته شول او ویې ویل: «مونږ به څه څښو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_24.mp3', '', 1761754199, 1761754199),
(52626, 'Exodus 15:25', 'Exodus', 15, 25, 'بیا موسی څښتن ته زارۍ وکړې او څښتن ورته د لرګي یوه ټوټه وروښودله. موسی هغه په اوبو کې وغورځوله او اوبه خوږې شوې. څښتن هلته هغوی ته قوانین ورکړل چې د هغو له مخې ژوند وکړي او هغوی وازمایي چې د هغه قوانینو ته غاړه ږدي او که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_25.mp3', '', 1761754199, 1761754199),
(52627, 'Exodus 15:26', 'Exodus', 15, 26, 'هغه وویل: «که چېرې تاسو خپل څښتن خدای ته په غور سره غوږ ونیسئ او هغه څه وکړئ چې د هغه په نظر کې ښه دي او که چېرې تاسو د هغه په امرونو باندې عمل وکړئ او د هغه د فرمانونو څخه پیروي وکړئ، نو زه به په تاسو باندې هغه ناروغۍ نازلې نه کړم کومې چې ما په مصریانو باندې نازلې کړې وې. ځکه چې زه څښتن یم او زه تاسو ته شفا درکوونکی یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_26.mp3', '', 1761754199, 1761754199),
(52628, 'Exodus 15:27', 'Exodus', 15, 27, 'بیا هغوی ایلیم ته راغلل. هلته دولس چینې او د خرما اویا ونې وې. نو هغوی هلته د چینو په غاړه خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_27.mp3', '', 1761754199, 1761754199),
(52629, 'Judges 3:1', 'Judges', 3, 1, 'نو څښتن په کنعان کې ځینې قومونه پرېښودل چې د هغوی په وسیله هغه اسراییلیان وازمایي چې د کنعان په جګړو کې یې برخه نه وه اخیستې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_1.mp3', '', 1761754199, 1761754199),
(52630, 'Judges 3:2', 'Judges', 3, 2, 'هغه د دې دپاره دا کار وکړ چې د اسراییلو هر نوی نسل باید دا زده کړي چې څنګه جګړه وکړي، په ځانګړې توګه هغه خلک چې مخکې د جګړې ډګر ته نه وو تللي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_2.mp3', '', 1761754199, 1761754199),
(52631, 'Judges 3:3', 'Judges', 3, 3, 'هغه قومونه چې په دې خاوره کې پاتې شوي وو دا وو: هغه فلسطینیان چې په پنځو ښارونو کې وو، ټول کنعانیان، صیدونیان او همدارنګه حویان چې د لبنان په غرونو کې د بعل حرمون څخه نیولې د حمات تر غاښي پورې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_3.mp3', '', 1761754199, 1761754199),
(52632, 'Judges 3:4', 'Judges', 3, 4, 'څښتن دا خلک د دې دپاره پریښي وو چې اسراییلیان ورباندې وازمایي او وګوري چې ایا هغوی د څښتن هغو حکمونو ته چې د موسی په وسیله د هغوی نیکونو ته ورکړل شوي وو، غاړه ږدي او که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_4.mp3', '', 1761754199, 1761754199),
(52633, 'Judges 3:5', 'Judges', 3, 5, 'نو اسراییلیان د کنعانیانو، حیتیانو، اموریانو، فرزیانو، حویانو او یبوسیانو په منځ کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_5.mp3', '', 1761754199, 1761754199),
(52634, 'Judges 3:6', 'Judges', 3, 6, 'دوی د هغوی لورګانې خپلو زامنو ته په نکاح کولې او خپلې لورګانې یې د هغوی زامنو ته په نکاح ورکولې او د هغوی د خدایانو عبادت به یې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_6.mp3', '', 1761754199, 1761754199),
(52635, 'Judges 3:7', 'Judges', 3, 7, 'د اسراییلو خلکو داسې کارونه وکړل چې د څښتن په نظر کې بد وو. د اسراییلو قوم خپل څښتن خدای هېر کړ او د بعل او اشیره د بتانو عبادت یې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_7.mp3', '', 1761754199, 1761754199),
(52636, 'Judges 3:8', 'Judges', 3, 8, 'نو څښتن په اسراییلو باندې ډېر په قهر شو او هغوی یې د بین النهرین پاچا کوشان رشعتایم ته په لاس ورکړل او هغه اته کاله په هغوی باندې حکومت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_8.mp3', '', 1761754199, 1761754199),
(52637, 'Judges 3:9', 'Judges', 3, 9, 'بیا اسراییلیانو څښتن ته فریاد وکړ، هغه ورته د کالیب د کشر ورور قناز زوی عتني ییل راولېږه چې هغوی وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_9.mp3', '', 1761754199, 1761754199),
(52638, 'Judges 3:10', 'Judges', 3, 10, 'د څښتن روح په هغه باندې نازل شو او هغه د اسراییلو مشر شو. عتني ییل جګړې ته لاړ او څښتن هغه د بین النهرین په پاچا کوشان رشعتایم باندې بریالی کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_10.mp3', '', 1761754199, 1761754199),
(52639, 'Judges 3:11', 'Judges', 3, 11, 'د اسراییلو په خاوره کې څلوېښت کاله ارامي وه او وروسته بیا عتني ییل مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_11.mp3', '', 1761754199, 1761754199),
(52640, 'Judges 3:12', 'Judges', 3, 12, 'د اسراییلو خلکو بیا داسې کارونه وکړل چې د څښتن په نظر کې بد وو. د هغوی د بدیو له امله څښتن عجلون د موآب پاچا د اسراییلو په وړاندې قوي کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_12.mp3', '', 1761754199, 1761754199),
(52641, 'Judges 3:13', 'Judges', 3, 13, 'عجلون د عمونیانو او عمالیقیانو سره یوځای شو. عجلون راغی او په اسراییلو باندې یې حمله وکړه او هغوی اریحا یعنې د خرما د ونو ښار ونیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_13.mp3', '', 1761754199, 1761754199),
(52642, 'Judges 3:14', 'Judges', 3, 14, 'د موآب پاچا عجلون په اسراییلیانو باندې اتلس کاله حکومت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_14.mp3', '', 1761754199, 1761754199),
(52643, 'Judges 3:15', 'Judges', 3, 15, 'بیا اسراییلیانو څښتن ته فریاد وکړ. هغه دوی ته یو کس ورولېږه چې دوی وژغوري. د هغه نوم ایهود ؤ چې چپ لاسی ؤ او د جیرا زوی ؤ چې د بنیامین د قبیلې څخه ؤ. اسراییلیانو د هغه په لاس د موآب پاچا عجلون ته باج ولېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_15.mp3', '', 1761754199, 1761754199),
(52644, 'Judges 3:16', 'Judges', 3, 16, 'ایهود یوه دوه مخې توره جوړه کړې وه چې نیم متر اوږده وه. هغه دا توره د خپلو کالیو لاندې په خپل ښي ورون باندې وتړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_16.mp3', '', 1761754199, 1761754199),
(52645, 'Judges 3:17', 'Judges', 3, 17, 'هغه د موآب پاچا عجلون ته چې ډېر چاغ سړی ؤ، باج وړاندې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_17.mp3', '', 1761754199, 1761754199),
(52646, 'Judges 3:18', 'Judges', 3, 18, 'کله چې ایهود هغه ته باج وړاندې کړ، هغه دا کسان چې باج یې وړی ؤ بېرته خپلو کورونو ته ولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_18.mp3', '', 1761754199, 1761754199),
(52647, 'Judges 3:19', 'Judges', 3, 19, 'خو ایهود په خپله د هغو مجسمو سره چې جلجال ته نژدې وې راوګرځېده، بېرته پاچا ته ورغی او ورته ویې ویل: «ای پاچا زه ستاسو دپاره یو پټ پیغام لرم.» پاچا خپلو خدمتګارانو ته وویل: «مونږ یوازې پرېږدئ!» او هغوی ټول ووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_19.mp3', '', 1761754199, 1761754199),
(52648, 'Judges 3:20', 'Judges', 3, 20, 'په داسې حال کې چې پاچا په خپلې هواداره بالاخانه کې یوازې ناست ؤ، ایهود هغه ته ورغی او ورته ویې ویل: «زه ستاسو دپاره د خدای له خوا یو پیغام لرم.» پاچا پاڅېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_20.mp3', '', 1761754199, 1761754199),
(52649, 'Judges 3:21', 'Judges', 3, 21, 'ایهود په خپل چپ لاس باندې د خپل ښي اړخ څخه توره راوویستله او د پاچا په ګېډه کې یې ورومنډله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_21.mp3', '', 1761754199, 1761754199),
(52650, 'Judges 3:22', 'Judges', 3, 22, 'توره د لاستي سره د هغه په ګېډه کې ننوته او د پښو له منځ څخه یې راووتله. ایهود د هغه د ګېډې څخه توره ونه ویستله او د هغه په وازګه کې پټه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_22.mp3', '', 1761754199, 1761754199),
(52651, 'Judges 3:23', 'Judges', 3, 23, 'بیا ایهود برنډې ته ووت. هغه پاچا پسې د کوټې دروازې بندې او قلف کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_23.mp3', '', 1761754199, 1761754199),
(52652, 'Judges 3:24', 'Judges', 3, 24, 'د ایهود د تګ څخه وروسته د پاچا خدمتګاران راغلل او ویې لیدل چې د کوټې دروازې قلف دي. هغوی فکر کاوه چې پاچا به دننه خپل حاجت پوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_24.mp3', '', 1761754199, 1761754199),
(52653, 'Judges 3:25', 'Judges', 3, 25, 'هغوی زیات انتظار وویست، تر هغې پورې چې وارخطا شول. خو کله چې هغه د کوټې دروازې خلاصې نه کړې، هغوی کلي واخیستله او دروازې یې خلاصې کړې. هغوی ولیدل چې بادار یې په غولي باندې مړ پروت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_25.mp3', '', 1761754199, 1761754199),
(52654, 'Judges 3:26', 'Judges', 3, 26, 'په هغه وخت کې چې هغوی انتظار کاوه، ایهود وتښتېده. هغه د مجسمو څخه تېر شو او سعیرت ته ورسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_26.mp3', '', 1761754199, 1761754199),
(52655, 'Judges 3:27', 'Judges', 3, 27, 'کله چې ایهود د افرایم غرنۍ سیمې ته ورسېده، نو سرنی یې وواهه او اسراییلیان د هغه سره د غونډیو څخه راښکته شول او هغه یې مشري کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_27.mp3', '', 1761754199, 1761754199),
(52656, 'Judges 3:28', 'Judges', 3, 28, 'هغوی ته یې وویل: «ما پسې راځئ! ځکه چې څښتن ستاسو دښمن یعنې موآب تاسو ته تسلیم کړی دی.» نو دوی په هغه پسې روان شول او د اردن ګودرونه یې چې موآب ته د تېرېدلو لاره وه ونیول او څوک یې نه پرېښودل چې د هغو څخه تېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_28.mp3', '', 1761754199, 1761754199),
(52657, 'Judges 3:29', 'Judges', 3, 29, 'په هغه ورځ هغوی د موآبیانو نژدې لس زره تکړه عسکر ووژل، هېچا ونه شو کولای چې وتښتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_29.mp3', '', 1761754199, 1761754199),
(52658, 'Judges 3:30', 'Judges', 3, 30, 'نو اسراییلیانو موآبیانو ته ماتې ورکړه او د اسراییلو په خاوره کې اتیا کاله ارامي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_30.mp3', '', 1761754199, 1761754199),
(52659, 'Judges 3:31', 'Judges', 3, 31, 'د ایهود څخه وروسته شمجر د عنات زوی مشر شو. هغه په چوکه باندې شپږ سوه فلسطینیان ووژل او اسراییلیان یې ورڅخه وژغورل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges3_verse_31.mp3', '', 1761754199, 1761754199),
(52660, 'Exodus 22:1', 'Exodus', 22, 1, 'که چېرې یو سړی یو غویی یا یو پسه غلا کړي او هغه حلال یا خرڅ کړي، نو هغه باید د هر غویي په بدل کې پنځه غویان او د هر پسه په بدل کې څلور پسونه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_1.mp3', '', 1761754199, 1761754199),
(52661, 'Exodus 22:5', 'Exodus', 22, 5, 'که چېرې یو سړی خپل حیوانات په یو پټي یا د انګورو په باغ کې څروي او هغه پرېږدي چې وګرځي او د بل سړي په پټي کې وڅریږي، نو هغه باید د خپل پټي یا د انګورو د باغ تر ټولو ښه حاصل په تاوان کې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_5.mp3', '', 1761754199, 1761754199),
(52662, 'Exodus 22:6', 'Exodus', 22, 6, 'که چېرې یو څوک په خپل پټي کې اور ولګوي او دا اور د اغزیو په وسیله د بل چا پټي ته خپور شي او د هغه ګېډۍ یا ولاړې غلې دانې وسوځوي، نو هرچا چې اور لګولی وي، باید پوره تاوان یې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_6.mp3', '', 1761754199, 1761754199),
(52663, 'Exodus 22:7', 'Exodus', 22, 7, 'که چېرې یو سړی بل چاته پیسې یا قیمتي شیان د امانت په توګه ورکړي او هغه د هغه سړي د کور څخه غلا شي، که چېرې غل ونیول شي، نو هغه باید دوه چنده بیه ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_7.mp3', '', 1761754199, 1761754199),
(52664, 'Exodus 22:8', 'Exodus', 22, 8, 'خو که چېرې هغه غل پیدا نه شي، د کور خاوند باید د قاضي په حضور کې ځان حاضر کړي او په دې ځای کې به هغه قسم خوري چې هغه د دې سړي شتمني نه ده غلا کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_8.mp3', '', 1761754199, 1761754199),
(52665, 'Exodus 22:9', 'Exodus', 22, 9, 'فرض کړئ د دوه کسانو ترمنځ د غویي، خره، پسه، کالیو یا نورو شیانو په سر شخړه ده او هر یو وایي چې هغه زما دي. نو دواړه خواوې دې د پرېکړې کولو دپاره قاضي ته لاړ شي. نو کوم یو چې د قاضي له خوا مجرم وګڼل شو، هغه بل کس ته باید دوه چنده تاوان ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_9.mp3', '', 1761754199, 1761754199),
(52666, 'Exodus 22:10', 'Exodus', 22, 10, 'که چېرې یو سړی خپل خر، غویی، پسه یا کوم بل حیوان بل چاته د امانت په توګه ورکړي او هغه مړ یا زخمي شي یا په داسې وخت کې غلا شي چې هېڅوک یې ونه ویني،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_10.mp3', '', 1761754199, 1761754199),
(52667, 'Exodus 22:11', 'Exodus', 22, 11, 'د هغوی ترمنځ به دا شخړه د څښتن په نوم په قسم خوړلو سره حل شي چې هغه سړي د دې بل سړي حیوان نه دی غلا کړی. نو خاوند دې دا ومني او هېڅ تاوان ته اړتیا نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_11.mp3', '', 1761754199, 1761754199),
(52668, 'Exodus 22:12', 'Exodus', 22, 12, 'خو که چېرې دا حیوان غلا شوی وي، هغه سړی باید د هغه خاوند ته تاوان ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_12.mp3', '', 1761754199, 1761754199),
(52669, 'Exodus 22:13', 'Exodus', 22, 13, 'که چېرې هغه د کوم وحشي حیوان له خوا وژل شوی وي، هغه سړی دې د هغه حیوان د بدن پاتې برخه د ثبوت په ډول د هغه خاوند ته راوړي، نو دا لازمه نه ده چې هغه د وژل شوي حیوان په خاطر تاوان ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_13.mp3', '', 1761754199, 1761754199),
(52670, 'Exodus 22:14', 'Exodus', 22, 14, 'که چېرې یو سړی د بل چا څخه یو حیوان په پور واخلي او هغه په داسې وخت کې زخمي یا مړ شي چې د هغه خاوند حاضر نه وي، هغه یې باید تاوان ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_14.mp3', '', 1761754199, 1761754199),
(52671, 'Exodus 22:15', 'Exodus', 22, 15, 'خو که چېرې دا پېښه د هغه د خاوند په شتون کې وشي، نو د تاوان ورکولو اړتیا نشته. که چېرې دا حیوان په کرایه نیول شوی وي، نو د کرایې پیسې چې خاوند ته یې ورکړل شوې دي د هغه تاوان پوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_15.mp3', '', 1761754199, 1761754199),
(52672, 'Exodus 22:16', 'Exodus', 22, 16, 'که چېرې یو سړی یوه داسې پېغله چې چاته کوژدن شوې نه وي وغولوي او د هغې سره زنا وکړي، نو هغه باید مهر ورکړي او د هغې سره دې واده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_16.mp3', '', 1761754199, 1761754199),
(52673, 'Exodus 22:17', 'Exodus', 22, 17, 'که چېرې د هغې پلار بیخي راضي نه وي چې خپله لور هغه ته ورکړي، بیاهم باید هغه کس د پېغلې پلار ته د ناوې د مهر په اندازه پیسې ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_17.mp3', '', 1761754199, 1761754199),
(52674, 'Exodus 22:18', 'Exodus', 22, 18, 'کوډګره ژوندۍ مه پرېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_18.mp3', '', 1761754199, 1761754199),
(52675, 'Exodus 22:19', 'Exodus', 22, 19, 'هرڅوک چې د یو حیوان سره جنسي اړیکې لري، باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_19.mp3', '', 1761754199, 1761754199),
(52676, 'Exodus 22:20', 'Exodus', 22, 20, 'هرڅوک چې د څښتن څخه پرته بل خدای ته قرباني وکړي، باید له منځه یووړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_20.mp3', '', 1761754199, 1761754199),
(52677, 'Exodus 22:21', 'Exodus', 22, 21, 'د یو پردي سړي سره بد چلند مه کوئ یا ظلم ورباندې مه کوئ، یاد ساتئ چې تاسو هم په مصر کې پردي وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_21.mp3', '', 1761754199, 1761754199),
(52678, 'Exodus 22:22', 'Exodus', 22, 22, 'د کونډې یا یتیم سره بد چلند مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_22.mp3', '', 1761754199, 1761754199),
(52679, 'Exodus 22:23', 'Exodus', 22, 23, 'که چېرې تاسو داسې وکړئ او هغوی ماته د مرستې دپاره فریاد وکړي، زه به د هغوی دعا قبوله کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_23.mp3', '', 1761754199, 1761754199),
(52680, 'Exodus 22:24', 'Exodus', 22, 24, 'زه به په قهر شم او تاسو به په جنګ کې ووژنم. ستاسو ښځې به کونډې شي او اولادونه به مو یتیمان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_24.mp3', '', 1761754199, 1761754199),
(52681, 'Exodus 22:25', 'Exodus', 22, 25, 'که چېرې تاسو زما د قوم څخه کوم غریب ته پیسې په پور ورکړئ، د یو پور ورکوونکي په شان عمل ورسره مه کوئ او هغه مه مجبوروئ چې سود درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_25.mp3', '', 1761754199, 1761754199),
(52682, 'Exodus 22:26', 'Exodus', 22, 26, 'که چېرې تاسو د یو چا چپنه په ضمانت واخلئ، باید هغه د لمرپرېواته څخه مخکې بېرته ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_26.mp3', '', 1761754199, 1761754199),
(52683, 'Exodus 22:27', 'Exodus', 22, 27, 'ځکه چې دا د هغه یوازېني کالي دي چې هغه ورباندې تود وي. کېدای شي چې د هغه سره بل داسې شی نه وي چې هغه په کې ویده شي. که چېرې هغه ماته د مرستې دپاره فریاد وکړي، زه به د هغه دعا قبوله کړم، ځکه چې زه رحیم یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_27.mp3', '', 1761754199, 1761754199),
(52684, 'Exodus 22:28', 'Exodus', 22, 28, 'د خدای په اړه بدې خبرې مه کوئ او نه د خپل قوم کوم مشر ته ښېرا کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_28.mp3', '', 1761754199, 1761754199),
(52685, 'Exodus 22:29', 'Exodus', 22, 29, 'د خپلو غلو دانو، د انګورو د شربتونو او زیتونو د تېلو د نذرانو په ورکولو کې ځنډ مه کوئ. تاسو باید خپل لومړني زېږېدلي زامن ماته وقف کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_29.mp3', '', 1761754199, 1761754199),
(52686, 'Exodus 22:30', 'Exodus', 22, 30, 'د خپلو غویانو او پسونو لومړني زېږېدل شوي بچي ماته راکړئ. پرېږدئ چې لومړني زېږېدل شوي نران بچي د خپلو میندو سره اووه ورځې پاتې شي او په اتمه ورځ یې ماته راکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_30.mp3', '', 1761754199, 1761754199),
(52687, 'Exodus 22:31', 'Exodus', 22, 31, 'تاسو باید زما سپېڅلی قوم اوسئ. د داسې حیوان غوښه مه خورئ چې وحشي حیواناتو داړلی وي. هغه سپیانو ته واچوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus22_verse_31.mp3', '', 1761754199, 1761754199),
(52688, 'Haggai 1:1', 'Haggai', 1, 1, 'د داريوس بادشاه د بادشاهۍ په دوېم کال د شپږمې مياشتې په اوله ورځ، د مالِک خُدائ کلام د حجى پېغمبر په وسيله زرُبابل د شلتى‌اېل په زوئ نازل شو چې د يهوداه حکمران وو، او يشوَع ته چې د مشر اِمام يهوصدق زوئ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_1.mp3', '', 1761754199, 1761754199),
(52689, 'Haggai 1:2', 'Haggai', 1, 2, '”دا هغه څۀ دى چې مالِک خُدائ ربُ الافواج يې فرمائى، دا خلق وائى چې د مالِک خُدائ د کور بيا جوړولو وخت لا نۀ دے راغلے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_2.mp3', '', 1761754199, 1761754199),
(52690, 'Haggai 1:3', 'Haggai', 1, 3, 'بيا د مالِک خُدائ پېغام د حجى پېغمبر په ذريعه راغلو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_3.mp3', '', 1761754199, 1761754199),
(52691, 'Haggai 1:4', 'Haggai', 1, 4, '”آيا تاسو ته دا ښۀ ښکارى چې زما کور کنډر پروت وى او تاسو په عالى شان کورونو کښې اوسېږئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_4.mp3', '', 1761754199, 1761754199),
(52692, 'Haggai 1:5', 'Haggai', 1, 5, 'اوس مالِک خُدائ ربُ الافواج فرمائى، تاسو سره چې څۀ کيږى ورباندې غور وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_5.mp3', '', 1761754199, 1761754199),
(52693, 'Haggai 1:6', 'Haggai', 1, 6, 'تاسو ډېر تخم کَرلے دے، خو فصل مو لږ رېبلے دے. تاسو خوراک کوئ خو ورباندې مړېږئ نه. تاسو اوبۀ څښئ، خو تنده مو پرې نۀ ختميږى. تاسو جامې اغوندئ، خو پرې نۀ ګرمېږئ. تاسو تنخواه ګټئ، خو صرف په هغه بټوه کښې اچولو دپاره چې په کښې سورى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_6.mp3', '', 1761754199, 1761754199),
(52694, 'Haggai 1:7', 'Haggai', 1, 7, 'مالِک خُدائ ربُ الافواج فرمائى چې په خپلو کارونو ډېر غور کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_7.mp3', '', 1761754199, 1761754199),
(52695, 'Haggai 1:8', 'Haggai', 1, 8, 'بره غر ته لاړ شئ او لرګى ترې لاندې راوړئ، او زما کور جوړ کړئ، نو چې زۀ پرې خوشحاله شم او عزتمند شم، مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_8.mp3', '', 1761754199, 1761754199),
(52696, 'Haggai 1:9', 'Haggai', 1, 9, 'تاسو د ډېرو په طمع وئ، خو وګورئ، دا لږ وختل. تاسو چې کور ته څۀ راوړل، هغه ما په هوا کښې والوځول. ولې؟ مالِک خُدائ ربُ الافواج فرمائى. زما د کور په وجه چې ګډ‌وډ پروت دے، او تاسو ټول په خپلو کورونو جوړولو کښې مصروف يئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_9.mp3', '', 1761754199, 1761754199),
(52697, 'Haggai 1:10', 'Haggai', 1, 10, 'نو ځکه ستاسو په وجه، آسمانونو پرخه ورول او زمکې فصل کول بند کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_10.mp3', '', 1761754199, 1761754199),
(52698, 'Haggai 1:11', 'Haggai', 1, 11, 'ما د اوچ کالۍ حکم کړے دے چې په زمکه او غرونو، په غله، په نوې ميو، په زيتُونو تېلو او په هر قسمه پېداوار چې زمکه يې کوى، په انسانانو او ځناورو، او ستاسو د لاسونو په محنت دې راشى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_11.mp3', '', 1761754199, 1761754199),
(52699, 'Haggai 1:12', 'Haggai', 1, 12, 'بيا زرُبابل د شلتى‌اېل زوئ، يشوَع د مشر اِمام يهوصدق زوئ، او د مالِک خُدائ پاتې شوو ټولو خلقو د مالِک خُدائ د هغوئ د خُدائ پاک خبرې ومنلې چې د حجى پېغمبر په ذريعه وئيلے شوې وې چې مالِک خُدائ د هغوئ خُدائ پاک هغه رالېږلے وو. او خلق د مالِک خُدائ نه ويرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_12.mp3', '', 1761754199, 1761754199),
(52700, 'Haggai 1:13', 'Haggai', 1, 13, 'بيا حجى، د خُدائ پاک پېغمبر، خلقو ته د مالِک خُدائ دا پېغام ورسولو، ”زۀ ستاسو مل يم، مالِک خُدائ فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_13.mp3', '', 1761754199, 1761754199),
(52701, 'Haggai 1:14', 'Haggai', 1, 14, 'نو مالِک خُدائ د زرُبابل د شلتى‌اېل د زوئ جذبه راپاروله چې د يهوداه حاکِم وو، او د يشوَع جذبه چې د مشر اِمام يهوصدق زوئ وو، او د مالِک خُدائ د ټولو ژوندى پاتې شوو خلقو جذبه. هغوئ راغلل او د مالِک خُدائ ربُ الافواج چې د هغوئ پاک خُدائ وو په کور يې کار شروع کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_14.mp3', '', 1761754199, 1761754199),
(52702, 'Haggai 1:15', 'Haggai', 1, 15, 'دا کار د داريوس بادشاه د بادشاهۍ په دوېم کال د شپږمې مياشتې په څليريشتمه ورځ شروع شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/haggai1_verse_15.mp3', '', 1761754199, 1761754199),
(52703, 'Psalms 101:1', 'Psalms', 101, 1, 'زه به ووایم سندره د تلپاتې مینې او انصاف ای څښتنه، تاته به ووایمه زه د ثنا سندره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_1.mp3', '', 1761754199, 1761754199),
(52704, 'Psalms 101:2', 'Psalms', 101, 2, 'زه به کومه پام چې خپل ژوند تېر کړم بې‌ګناه ته به زما مرستې ته کله راځې؟ زه به په خپل کور کې ژوند کومه په صداقت سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_2.mp3', '', 1761754199, 1761754199),
(52705, 'Psalms 101:3', 'Psalms', 101, 3, 'بدو شیانو ته کتلو نه به ډډه کوم د بې‌ایمانو د کارونو نه زه کرکه کوم زه به هغوی سره هېڅ کار نه لرم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_3.mp3', '', 1761754199, 1761754199),
(52706, 'Psalms 101:4', 'Psalms', 101, 4, 'زه به نه کړم درغلي هېڅ کار به نه لرم بدۍ سره زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_4.mp3', '', 1761754199, 1761754199),
(52707, 'Psalms 101:5', 'Psalms', 101, 5, 'زه به هغوی له منځه یوسم چې په پټه کړي غیبت د نورو زغملی نه شم هغه خلک چې لري زړونه کبرجن او مغرورې سترګې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_5.mp3', '', 1761754199, 1761754199),
(52708, 'Psalms 101:6', 'Psalms', 101, 6, 'زه نېک ګڼمه هغه خلک چې وفادار دي هغوی به پرېږدم ما سره واوسیږي هغه خلک چې بې‌عیبه دي وي به هغوی ته اجازه چې خدمت وکړي زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_6.mp3', '', 1761754199, 1761754199),
(52709, 'Psalms 101:7', 'Psalms', 101, 7, 'چلباز به نه اوسیږي زما په کور کې دروغجن به پاتې نه شي زما حضور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_7.mp3', '', 1761754199, 1761754199),
(52710, 'Psalms 101:8', 'Psalms', 101, 8, 'نابودوم بدکاره خلک هره ورځ په خپل وطن کې او خراب خلک به د څښتن له ښاره وشړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms101_verse_8.mp3', '', 1761754199, 1761754199);